import{_ as a,a as i,b as p,c as o,d as t,e,f as r,g as n,h as s,i as u,j as c}from"./chunks/ruankao_20250402172124.D_aWAre3.js";import{_ as h,o as d,c as b,at as _}from"./chunks/framework.CY22Hent.js";const q="/assets/ruankao_2025-11-05_160927_874.D6QW4Lq3.png",k="/assets/ruankao_20250512143939.DEGEphwQ.png",m="/assets/ruankao_20250512145216.DCtkABJd.png",g="/assets/ruankao_20251107233012.BwJ8vUv0.png",P="/assets/ruankao_20251107233109.D67Thd5a.png",C="/assets/ruankao_20251107191451.BoUvYBbR.png",f="/assets/ruankao_20251108000353.RsU5BgIa.png",x="/assets/ruankao_20250514111327.Dq1svYU_.png",y="/assets/ruankao_20250514113816.BsB4LWW8.png",M="/assets/ruankao_20250514152906.D20G6oYt.png",I="/assets/ruankao_20251107204141.CtALhtgz.png",V=JSON.parse('{"title":"软件设计师笔记05_软件工程基础_精简考点","description":"","frontmatter":{"title":"软件设计师笔记05_软件工程基础_精简考点","date":"2025-03-31T00:00:00.000Z","lastUpdated":"2025-10-26T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记05_软件工程基础_精简考点.md","filePath":"blogs/软考/软件设计师笔记05_软件工程基础_精简考点.md"}'),E={name:"blogs/软考/软件设计师笔记05_软件工程基础_精简考点.md"};function T(z,l,G,L,D,S){return d(),b("div",null,[...l[0]||(l[0]=[_('<p>[toc]</p><h1 id="软件设计师笔记05-软件工程基础-精简考点" tabindex="-1">软件设计师笔记05_软件工程基础_精简考点 <a class="header-anchor" href="#软件设计师笔记05-软件工程基础-精简考点" aria-label="Permalink to &quot;软件设计师笔记05_软件工程基础_精简考点&quot;">​</a></h1><p>科目一考试中占2-5分左右。</p><p><img src="'+q+'" alt="ruankao_2025-11-05_160927_874.png" loading="lazy"></p><h2 id="软件工程概述" tabindex="-1">软件工程概述 <a class="header-anchor" href="#软件工程概述" aria-label="Permalink to &quot;软件工程概述&quot;">​</a></h2><ul><li>软件工程的基本要素：方法、工具、过程。</li></ul><h3 id="软件生存周期" tabindex="-1">软件生存周期 <a class="header-anchor" href="#软件生存周期" aria-label="Permalink to &quot;软件生存周期&quot;">​</a></h3><p>一个软件产品或软件系统要经历孕育、诞生、成长、成熟、衰亡等阶段，一般称为软件生存周期。</p><p>软件生存周期包括以下七个方面：</p><ol><li>可行性分析与项目开发计划。这个阶段主要确定软件的开发目标及其可行性。参与该阶段的人员有用户、项目负责人、系统分析师。产生的文档有可行性分析报告、项目开发计划。</li><li>需求分析。该阶段的任务不是具体的解决问题，而是要确定软件系统要做什么，确定软件系统的功能、性能、数据和界面等要求，从而确定系统的逻辑模型。参与该阶段的人员有用户、项目负责人、系统分析师。产生的文档主要是软件需求说明书。</li><li>概要设计。该阶段开发人员把确定的各项功能需求转换成需要的体系结构。概要设计就是设计软件的结构，明确软件由哪些模块组成，这些模块层次结构是怎样的，调用关系是怎样的，每个模块的功能是什么。参与该阶段的人员有系统分析师、软件设计师。产生的文档主要是概要设计说明书。</li><li>详细设计。该阶段的主要任务是对每个模块的功能进一步详细、具体的描述。参与该阶段的人员有软件设计师、程序员。产生的文档主要是详细设计文档。</li><li>编码。把每个模块的控制结构转换成计算机可接受的程序代码，即写成某种特定程序设计语言表示的源程序清单。</li><li>测试。测试是保证软件质量的重要手段。参加测试的人员通常是另一部门（或单位）的软件设计师或系统分析师。产生的文档主要是软件测试计划、测试用例、测试报告。</li><li>维护。软件维护是软件生存周期中时间最长的阶段。软件已交付且正式投入使用后，便进入维护阶段。对软件进行修改的原因包括：①运行中发现隐含的错误而需要修改；②为了适应变化的（或变化后的）工作环境而修改；③需要对软件功能进行扩充、增强而进行的修改；④为将来软件维护活动做预先准备。</li></ol><h2 id="能力成熟度模型-cmm-⭐" tabindex="-1">能力成熟度模型（CMM） ⭐ <a class="header-anchor" href="#能力成熟度模型-cmm-⭐" aria-label="Permalink to &quot;能力成熟度模型（CMM） ⭐&quot;">​</a></h2><p>能力成熟度模型（CMM）将软件的改进分为五个成熟度级别。</p><p><img src="'+a+'" alt="ruankao_20250512160548.png" loading="lazy"></p><blockquote><p>记忆点</p></blockquote><ul><li>第一级：初始级：制度缺乏，混乱无序，依靠个人管理。</li><li>第二级：可重复级：建立基本管理制度。一定程度上可重复类似项目的软件开发。</li><li>第三级：已定义级：已文档化，标准化。</li><li>第四级：已管理级：有对应的测量指标。并利用统计工具进行分析和改进。</li><li>第五级：优化级：基于工具，持续改进软件过程，质量稳步改进。</li></ul><h2 id="能力成熟度模型集成-cmmi-⭐" tabindex="-1">能力成熟度模型集成（CMMI） ⭐ <a class="header-anchor" href="#能力成熟度模型集成-cmmi-⭐" aria-label="Permalink to &quot;能力成熟度模型集成（CMMI） ⭐&quot;">​</a></h2><p>CMMI 提供了两种表示方法：阶段式模型和连续式模型。</p><p>CMMI的连续式模型表达 中包括六个过程域能力等级。</p><ul><li>CL0（未完成的）：过程域未执行或未得到CL1中定义的所有目标。</li><li>CL1（已执行的）：其共性目标是过程将可标识的输入工作产品转换成可标识的输出工作产品，以实现支持过程域的特定目标。</li><li>CL2（已管理的）：其共性目标是集中于已管理的过程的制度化。所有工作任务和工作产品都被监控、控制、和评审。</li><li>CL3（已定义级的）：其共性目标集中于已定义的过程的制度化。过程是按照组织的裁剪指南从组织的标准过程中裁剪得到的，还必须收集过程资产和过程的度量，并用于将来对过程的改进。</li><li>CL4（定量管理的）：其共性目标集中于可定量管理的过程的制度化。使用测量和质量保证来控制和改进过程域，建立和使用关于质量和过程执行的质量目标作为管理准则。</li><li>CL5（优化的）：使用量化（统计学）手段改变和优化过程域，以满足客户的改变和持续改进计划中的过程域的功效。</li></ul><blockquote><p>记忆点</p></blockquote><ul><li>CL0（未完成的）：未执行或未达成CL1目标。</li><li>CL1（已执行的）：将可标识的输入工作产品转换成可标识的输出工作产品，以实现目标。</li><li>CL2（已管理的）：目标是集中于已管理的过程的制度化。所有都被监控、控制、和评审。</li><li>CL3（已定义级的）：目标集中于已定义的过程的制度化。标准化、文档化。</li><li>CL4（定量管理的）：目标集中于可定量管理的过程的制度化。测量、统计分析。</li><li>CL5（优化的）：使用量化手段改变和优化过程域。持续改进。</li></ul><h3 id="例题" tabindex="-1">例题 <a class="header-anchor" href="#例题" aria-label="Permalink to &quot;例题&quot;">​</a></h3><blockquote><p>例题1</p></blockquote><p>能力成熟度模型集成（CMMI）是若干过程模型的综合和改进。连续式模型和阶段式模型是CMMI提供的两种表示方法，而连续式模型包括6个过程域能力等级，其中（ CL5（优化的） ）使用量化（统计学）手段改变和优化过程域，以应对客户要求的改变和持续改进计划中的过程域的功效。</p><blockquote><p>例题2</p></blockquote><p>能力成熟度模型集成(CMMI)是若干过程模型的综合和改进。连续式模型和阶段式模型是CMMI提供的两种表示方法。连续式模型包括6个过程域能力等级，其中（ CL1(已执行的) ）的共性目标是过程将可标识的输入工作产品转换成可标识的输出工作产品,以实现支持过程域的特定目标。</p><h2 id="软件开发方法" tabindex="-1">软件开发方法 <a class="header-anchor" href="#软件开发方法" aria-label="Permalink to &quot;软件开发方法&quot;">​</a></h2><ul><li>原型化开发方法：适合需求不清晰，需求变化大且规模不太大时采用。</li><li>结构化开发方法：适合需求明确或需求变化不大。</li><li>面向对象开发方法：更好的复用性，关键在于建立一个全面、合理、统一的模型，分析、设计、实现三个阶段界限不明确。</li></ul><h2 id="软件过程模型" tabindex="-1">软件过程模型 <a class="header-anchor" href="#软件过程模型" aria-label="Permalink to &quot;软件过程模型&quot;">​</a></h2><p>典型的软件过程有瀑布模型、增量模型、演化模型（原型模型、螺旋模型）、喷泉模型、基于构件的开发模型和形式化方法模型等。</p><h3 id="瀑布模型" tabindex="-1">瀑布模型 <a class="header-anchor" href="#瀑布模型" aria-label="Permalink to &quot;瀑布模型&quot;">​</a></h3><p>瀑布模型的开发流程如同瀑布一般，一步一步的走下去，直到最后完成项目开发。</p><p>瀑布模型包括需求分析、设计、编码、测试、运行与维护共5个阶段。</p><p>如图所示 <img src="'+i+'" alt="ruankao_20241022153258.png" loading="lazy"></p><ul><li>瀑布模型的优点：容易理解、成本低、强调开发的阶段性早期计划及需求调查和产品测试</li><li>瀑布模型的缺点：只适用于需求明确或者二次开发(需求稳定)，当需求不明确时，最终开发的项目容易产生错误，有很大的缺陷。</li></ul><h3 id="v-模型" tabindex="-1">V 模型 <a class="header-anchor" href="#v-模型" aria-label="Permalink to &quot;V 模型&quot;">​</a></h3><p>V模型是瀑布模型的一个变体。如图所示。</p><p><img src="'+p+'" alt="ruankao_20241022153613.png" loading="lazy"></p><p>V 模型的特点是增加了很多轮测试，并且这些测试贯穿于软件开发的各个阶段，不像其他模型都是软件开发完成后测试，很大程度上保证了项目的准确性。</p><h3 id="增量模型" tabindex="-1">增量模型 <a class="header-anchor" href="#增量模型" aria-label="Permalink to &quot;增量模型&quot;">​</a></h3><p>增量模型：首先开发核心模块功能，而后与客户确认。之后再开发次核心模块的功能，即每次开发一部分功能，并与客户需求确认。最终完成项目开发，优先级最高的服务最先交付</p><p><span style="color:red;">增量模型也具有瀑布模型所有的优点。即增量模型就是分批次做，先核心功能，再叠加增量模块</span></p><p><span style="color:red;">注意：增量模型用于需求基本明确，但无法一次性全部确定的情况。</span></p><p><img src="'+o+'" alt="ruankao_20241022153858.png" loading="lazy"></p><ul><li>增量模型的优点：可交付的第一个增量版本所需要的成本和时间很少，所承担的风险不大。由于很快发布了第一个版本，因此可减少客户需求的变更。</li><li>增量模型的缺点：若客户需求不像早期思考的那样稳定和完整，那么一些增量就可能需要重新开发或重新发布；管理发生的成本、进度和配置的复杂性可能会超出组织的能力。</li></ul><h3 id="演化模型" tabindex="-1">演化模型 <a class="header-anchor" href="#演化模型" aria-label="Permalink to &quot;演化模型&quot;">​</a></h3><p>在开发过程中，软件开发人员需要一种专门应对不断演变的软件产品的过程模型。而演化模型是迭代的过程模型，特别适用于对软件需求缺乏准确认识的情况。</p><p>典型的演化模型有原型模型和螺旋模型等。</p><h4 id="原型模型" tabindex="-1">原型模型 <a class="header-anchor" href="#原型模型" aria-label="Permalink to &quot;原型模型&quot;">​</a></h4><p>原型模型：即快速原型开发，原型模型针对的就是需求不明确的情况，首先快速构造一个功能模板，演示给客户看，并按用户要求及时修改，中间再通过不断的演示与客户沟通，最终设计出项目，就不会出现与客户要求不符合的情况，采用的是迭代的思想。</p><p>原型模型如图所示。 <img src="'+t+'" alt="ruankao_20241022154358.png" loading="lazy"></p><h4 id="螺旋模型-针对需求不明确" tabindex="-1">螺旋模型(针对需求不明确) <a class="header-anchor" href="#螺旋模型-针对需求不明确" aria-label="Permalink to &quot;螺旋模型(针对需求不明确)&quot;">​</a></h4><p>螺旋模型是将瀑布模型和演化模型结合起来，加入了风险分析，弥补了这两种模型的不足。</p><p>螺旋模型适合用于庞大、复杂、高风险的系统。</p><p>螺旋模型将开发过程分为几个螺旋周期，每个螺旋周期大致和瀑布模型相符合。</p><p>螺旋模型如图所示。 <img src="'+e+'" alt="ruankao_20241022154510.png" loading="lazy"></p><p>螺旋模型将开发过程分为几个螺旋周期，每个螺旋周期大致和瀑布模型相符合，每个螺旋周期分为如下4个工作步骤。</p><ol><li>制订计划：确定软件目标，选定实施方案，明确项目开发的限制条件。</li><li>风险分析：对所选方案进行分析，识别风险，消除风险。</li><li>实施工程：实施软件开发，验证阶段性产品。</li><li>用户评估：评价开发工作，提出修正建议，建立下一个周期的开发计划。</li></ol><h3 id="喷泉模型" tabindex="-1">喷泉模型 <a class="header-anchor" href="#喷泉模型" aria-label="Permalink to &quot;喷泉模型&quot;">​</a></h3><p>喷泉模型：是一种以用户需求为动力，以对象作为驱动的模型，适合于面向对象的开发方法。使开发过程具有迭代性和无间隙性。</p><p>喷泉模型如图所示。 <img src="'+r+'" alt="ruankao_20251026213925.png" loading="lazy"></p><ul><li>优点：喷泉模型的各个阶段没有明显的界线，开发人员可以同步进行。其优点是可以提高软件项目的开发效率，节省开发时间。</li><li>缺点：这种模型要求严格管理文档，使得审核的难度加大。</li></ul><h3 id="各个软件过程模型总结-⭐" tabindex="-1">各个软件过程模型总结 ⭐ <a class="header-anchor" href="#各个软件过程模型总结-⭐" aria-label="Permalink to &quot;各个软件过程模型总结 ⭐&quot;">​</a></h3><p>针对需求明确的情况：</p><ul><li>瀑布模型：需求明确，如同瀑布一般，按阶段一步一步完成。</li><li>V模型：瀑布模型的变体。在瀑布模型的各个阶段上添加多轮测试。</li><li>增量模型：瀑布模型的变体。先开发核心功能，后开发附加功能。一个增量一个增量的开发。特点是可以很快发布了第一个版本。用于需求基本明确，但无法一次性全部确定的情况。</li></ul><p>演化模型：针对的就是需求不明确的情况。</p><ul><li>原型模型：采用快速迭代的思想。只适合小型软件系统的开发。</li><li><span style="color:red;">螺旋模型：是瀑布模型和原型模型的结合体。并加上了风险分析。螺旋模型将开发过程分为几个螺旋周期，每个螺旋周期大致和瀑布模型相符合。适合用于庞大、复杂、高风险的系统。</span></li></ul><p>喷泉模型：适合于面向对象的开发方法,可复用性高。使开发过程具有迭代性和无间隙性。</p><p><img src="'+n+'" alt="ruankao_20250513160613.png" loading="lazy"></p><blockquote><p>记忆点</p></blockquote><ul><li>需求明确 → 瀑布模型、V模型</li><li>需求基本明确，无法一次性确定的情况 → 增量模型</li><li>需求变化大 → 原型模型、螺旋模型</li><li>面向对象 → 喷泉模型、RUP</li><li>敏捷开发 → XP、Scrum</li></ul><h2 id="统一过程模型-up-rup-⭐" tabindex="-1">统一过程模型（UP/RUP） ⭐ <a class="header-anchor" href="#统一过程模型-up-rup-⭐" aria-label="Permalink to &quot;统一过程模型（UP/RUP） ⭐&quot;">​</a></h2><p>统一过程模型 分为 4 个阶段，按固定顺序执行。每个阶段都有特定的任务和产品。</p><p>统一过程的四个阶段及其产品：</p><ul><li>（1）起始阶段：专注于项目初创活动。</li><li>（2）精化阶段：在理解了最初领域范围之后，需要进行需求分析和架构演进。</li><li>（3）构建阶段：关注系统的构建，产生实现模型。</li><li>（4）移交阶段：关注软件提交方面的工作，产生软件增量。</li></ul><blockquote><p>记忆点</p></blockquote><ul><li>（1）起始阶段：关键词项目初创。</li><li>（2）精化阶段：关键词需求分析和架构演进。</li><li>（3）构建阶段：关键词系统构建，系统实现。</li><li>（4）移交阶段：关键词软件提交。</li></ul><h2 id="敏捷开发-⭐" tabindex="-1">敏捷开发 ⭐ <a class="header-anchor" href="#敏捷开发-⭐" aria-label="Permalink to &quot;敏捷开发 ⭐&quot;">​</a></h2><p>敏捷开发的总体目标是通过“尽可能早地、持续地对有价值的软件的交付”使客户满意。通过在软件开发过程中加入灵活性，敏捷方法使用户能够在开发周期的后期增加或改变需求。</p><p>敏捷开发方法，包括极限编程（XP）、水晶法（Crystal）、并列争球法（Scrum:）和自适应软件开发（ASD）等。</p><blockquote><p>总结</p></blockquote><ul><li>极限编程XP ： 是一种轻量级的软件开发方式。由价值观、原则、实践和行为4个部分组成。</li><li>水晶法Crystal ： 认为每一个不同的项目都需要一套不同的策略、约定和方法论。</li><li>并列争球法Scrum ： 使用迭代的方法，并按需求的优先级来实现产品。</li><li>敏捷统一过程(AUP) ： 采用“在大型上连续”以及在“在小型上迭代”的原理来构建软件系统。</li></ul><h2 id="系统设计" tabindex="-1">系统设计 <a class="header-anchor" href="#系统设计" aria-label="Permalink to &quot;系统设计&quot;">​</a></h2><p>概要设计主要包括:</p><ul><li>①软件系统总体结构设计;</li><li>②数据结构及数据库设计;</li><li>③编写概要设计文档(概要设计说明书、数据库设计说明书、用户手册及修订测试计划);</li><li>④评审。</li></ul><p>详细设计主要包括:</p><ul><li>①对每个模块进行详细设计;</li><li>②对模块内部的数据结构进行设计;</li><li>③对数据库进行物理设计，即确定数据库的物理结构:</li><li>④其他设计(代码设计、输入/输出设计、用户界面设计);</li><li>⑤编写详细设计说明书;</li><li>⑥评审。</li></ul><h2 id="项目活动图-里程碑-⭐️⭐️⭐️" tabindex="-1">项目活动图 里程碑 ⭐️⭐️⭐️ <a class="header-anchor" href="#项目活动图-里程碑-⭐️⭐️⭐️" aria-label="Permalink to &quot;项目活动图 里程碑 ⭐️⭐️⭐️&quot;">​</a></h2><p>考点：</p><p><span style="color:red;">① 项目活动图中的关键路径，其实就是完成该项目的最长路径 ，也是完成该项目的最少时间的路径。</span></p><p><span style="color:red;">② 项目活动图中完成该项目的最少时间由活动图中的最长路径决定。</span></p><p><span style="color:red;">③ 项目活动图中某个活动的松弛时间 = 最长路径的天数 - 包含该活动的最长路径的天数。</span></p><p><span style="color:red;">④ 在关键路径（最长路径）上的活动，其松弛时间为0为0，即不能提前或延迟。</span></p><blockquote><p>记忆点</p></blockquote><ul><li>项目活动图中的关键路径 ：最长路径 = 最短工期</li><li>某个活动的松弛时间 ：最长路径时间 - 包含该活动的最长路径时间</li></ul><h3 id="例题-1" tabindex="-1">例题 <a class="header-anchor" href="#例题-1" aria-label="Permalink to &quot;例题&quot;">​</a></h3><blockquote><p>真题案例</p></blockquote><p>2018年下半年</p><p>某软件项目的活动图如下图所示，其中顶点表示项目里程碑，连接顶点的边表示包含的活动，边上的数字表示活动的持续时间（天），则完成该项目的最少时间为（ ）天。活动FG的松驰时间为（ ）天。</p><p><img src="'+k+'" alt="ruankao_20250512143939.png" loading="lazy"></p><ul><li>A 20</li><li>B 37</li><li>C 38</li><li>D 46</li></ul><p>完成该项目的最少时间由活动图中的最长路径决定。</p><p>其中路径 A-D-F-H-J ：10+8+18+10=46 。因此完成该项目的最少时间为46天。</p><p>某个活动的松弛时间 = 最长路径的天数 - 包含该活动的最长路径的天数。</p><p>活动 FG 所在路径中的最长路径为A-D-F-G-J ，其长度为 10+8+3+7=28 （天）。</p><p>完成该项目的最少时间为46天。所以活动 FG 的松弛时间为 46 - 28 = 18 （天）。</p><blockquote><p>真题案例</p></blockquote><p>2023年上半年</p><p>下图是一个软件项目的活动图，其中顶点表示项目里程碑，连接顶点的边表示活动，则里程碑（ ）在关键路径上,关键路径长度为（ ）</p><p><img src="'+m+'" alt="ruankao_20250512145216.png" loading="lazy"></p><ul><li>A B</li><li>B E</li><li>C G</li><li>D I</li></ul><p>关键路径就是完成该项目的最长路径，也是完成该项目的最少时间的路径。</p><p>如图可知：A-C-E-H-J-K 所在路径是最长路径。该路径完成时间为23天。因此里程碑E在关键路径上。关键路径长度为23</p><blockquote><p>真题</p></blockquote><p><img src="'+g+'" alt="ruankao_20251107233012.png" loading="lazy"> 解析 <img src="'+P+'" alt="ruankao_20251107233109.png" loading="lazy"></p><blockquote><p>真题</p></blockquote><p><img src="'+C+'" alt="ruankao_20251107191451.png" loading="lazy"></p><p>试题分析:</p><p>先找出关键路径为 ABDGIKL ，其长度为22，所以最短工期为22天。</p><p>BD是关键路径上的活动，其总时差为0，不能耽搁，所以BD最多延误0天不会影响总工期。</p><p>答案:(15)C (16)A</p><h2 id="需求分析" tabindex="-1">需求分析 <a class="header-anchor" href="#需求分析" aria-label="Permalink to &quot;需求分析&quot;">​</a></h2><h3 id="需求分析方法" tabindex="-1">需求分析方法 <a class="header-anchor" href="#需求分析方法" aria-label="Permalink to &quot;需求分析方法&quot;">​</a></h3><ul><li>结构化分析：数据流图（DFD）、数据字典</li><li>面向对象分析：用例图、类图、活动图</li></ul><h2 id="软件测试" tabindex="-1">软件测试 <a class="header-anchor" href="#软件测试" aria-label="Permalink to &quot;软件测试&quot;">​</a></h2><ul><li>（1）单元测试：也称模块测试，侧重于模块中的内部处理逻辑和数据结构。</li><li>（2）集成测试：把模块组合起来进行测试，侧重于模块之间的交互和功能。</li><li>（3）系统测试：将已经确认的软件、硬件、外设、网络等其他因素结合在一起，进行系统级的测试。</li></ul><h3 id="例题-2" tabindex="-1">例题 <a class="header-anchor" href="#例题-2" aria-label="Permalink to &quot;例题&quot;">​</a></h3><blockquote><p>某软件系统在测试过程中，（）最适合发现模块之间的接口问题。</p></blockquote><p>正确答案 集成测试</p><blockquote><p>例题2</p></blockquote><p>白盒测试技术的各种覆盖方法中，（ 语句覆盖 ）具有最弱的错误发现能力。</p><blockquote><p>例题3</p></blockquote><p>软件产品的 Alpha 测试和 Beta 测试属于（ 确认测试 ）。</p><h3 id="测试方法" tabindex="-1">测试方法 <a class="header-anchor" href="#测试方法" aria-label="Permalink to &quot;测试方法&quot;">​</a></h3><p>软件测试的测试方法分为静态测试和动态测试。</p><blockquote><p>静态测试</p></blockquote><p>静态测试：是指采用人工检测和计算机辅助静态分析的手段对程序进行测试，包括人工检测、计算机辅助静态分析。</p><blockquote><p>动态测试</p></blockquote><p>动态测试：是指通过运行程序发现错误，一般采用黑盒测试和白盒测试。</p><h4 id="黑盒测试" tabindex="-1">黑盒测试 <a class="header-anchor" href="#黑盒测试" aria-label="Permalink to &quot;黑盒测试&quot;">​</a></h4><p>黑盒测试又称功能测试。完全不考虑软件的内部结构和处理算法，它只检查软件功能是否能按照软件需求说明书的要求正常使用。</p><p>常用的黑盒测试技术包括等价类划分、边界值分析、错误推测和因果图等。</p><h4 id="白盒测试-⭐" tabindex="-1">白盒测试 ⭐ <a class="header-anchor" href="#白盒测试-⭐" aria-label="Permalink to &quot;白盒测试 ⭐&quot;">​</a></h4><p>白盒测试，又称结构测试，主要用于单元测试阶段。它的前提是把程序看成装在一个透明的白盒子里，测试者完全知道程序的结构和处理算法。这种方法主要检测程序中的执行通路是否都能按预定要求正确工作。</p><blockquote><p>白盒测试的覆盖标准有六种,从弱到强如下。</p></blockquote><p>语句覆盖 &lt; 判定覆盖 &lt; 条件覆盖 &lt; 判定/条件覆盖 &lt; 条件组合覆盖 &lt; 路径覆盖</p><blockquote><p>六种覆盖总结(大白话理解)</p></blockquote><ul><li>语句覆盖(最弱)：把每一行代码都跑一遍就行。只要所有语句都执行到，就算达标</li><li>判定覆盖：每个if 判断，既要走成立，也要走不成立</li><li>条件覆盖：每个if 判断，判断里每一个小条件，都要取过真、取过假</li><li>判定/条件覆盖：同时满足判定覆盖 + 条件覆盖。</li><li>条件组合覆盖：把多个判断的所有真假排列组合全部试一遍</li><li>路径覆盖(最强)：把程序里所有能走的完整路线全部走一遍。</li></ul><blockquote><p>记忆点：</p></blockquote><ul><li>最弱：语句覆盖</li><li>最强：路径覆盖。路径覆盖可以覆盖前面所有五种</li></ul><p><span style="color:red;">条件组合覆盖 包含 判定/条件覆盖。即满足条件组合覆盖的测试用例，也一定满足判定/条件覆盖。</span></p><h3 id="测试的覆盖用例计算-例题" tabindex="-1">测试的覆盖用例计算 例题 <a class="header-anchor" href="#测试的覆盖用例计算-例题" aria-label="Permalink to &quot;测试的覆盖用例计算 例题&quot;">​</a></h3><p><img src="'+f+'" alt="ruankao_20251108000353.png" loading="lazy"></p><p>试题分析:</p><p>覆盖两条路径就能达到语句覆盖的要求，用两个测试用例即可。</p><p>路径覆盖需要把程序中的所有路径均覆盖一遍，需要四个用例。</p><p>整个程序流程图转化为节点图之后，一共11个节点、13条边，根据环路复杂度公式有 13-11+2=4。</p><p>答案:(35)B (36) D</p><h2 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h2><h3 id="沟通路径数公式-⭐" tabindex="-1">沟通路径数公式 ⭐ <a class="header-anchor" href="#沟通路径数公式-⭐" aria-label="Permalink to &quot;沟通路径数公式 ⭐&quot;">​</a></h3><p><span style="color:red;">沟通路径数公式 = n × (n – 1) / 2</span></p><blockquote><p>例题1</p></blockquote><ul><li>由8位成员组成的开发团队中，一共有（ 28 ）条沟通路径. <ul><li>如果是采用有主程序员的沟通方式，只要7条路径。</li><li>如果是无主程序员的沟通方式。计算7+6+5+4+3+2+1，结果是28。</li></ul></li></ul><blockquote><p>例题2</p></blockquote><ul><li>在进行软件开发时，采用无主程序员的开发小组，成员之间相互平等;而主程序员负责制的开发小组，由一个主程序员和若干成员组成，成员之间没有沟通。在一个由8名开发人员构成的小组中，无主程序员组和主程序员组的沟通路径分别是（ 28 和 7 ）。 <ul><li>无主程序员组的开发小组，每两两开发人员之间都有沟通路径，因此，8人组成的开发小组沟通路径为完全连通无向图的边数，即 7+6+5+4+3+2+1</li><li>主程序员组中，除了主程序员外的每个开发人员只能和主程序员沟通，因此8人组成的开发小组的沟通路径8-1=7。</li></ul></li></ul><h3 id="甘特图-gantt-chart-⭐" tabindex="-1">甘特图（Gantt Chart） ⭐ <a class="header-anchor" href="#甘特图-gantt-chart-⭐" aria-label="Permalink to &quot;甘特图（Gantt Chart） ⭐&quot;">​</a></h3><p>甘特图 ：反映并行关系，无法反映依赖关系</p><p>Gantt图：又称为横道图，横轴表示时间，纵轴表示活动，以时间顺序表示活动，能反应活动间的并行关系，但无法反应活动之间的依赖关系。</p><p><img src="'+s+'" alt="ruankao_20251026224902.png" loading="lazy"></p><p><span style="color:red;">Gantt图能清晰地描述每个任务从何时开始，到何时结束，任务的进展情况以及各个任务之间的并行性。但是它不能清晰地反映出各任务之间的依赖关系，难以确定整个项目的关键所在，也不能反映计划中有潜力的部分。</span></p><h3 id="pert图-⭐" tabindex="-1">PERT图 ⭐ <a class="header-anchor" href="#pert图-⭐" aria-label="Permalink to &quot;PERT图 ⭐&quot;">​</a></h3><p>PERT图 ：反映依赖关系，无法反映并行关系</p><p>PERT图：类似于前趋图，是有向图，反应活动之间的依赖关系，有向边上标注活动运行的时间，但无法反应活动之间的并行关系</p><p><img src="'+u+'" alt="ruankao_20251026225058.png" loading="lazy"></p><p>PERT图不仅给出了每个任务的开始时间、结束时间和完成该任务所需的时间，还给出了任务之间的关系，即哪些任务完成后才能开始另外一些任务，以及如期完成整个工程的关键路径。</p><p>图中的松弛时间则反映了完成某些任务时可以推迟其开始时间或延长其所需完成的时间。但是，PERT图不能反映任务之间的并行关系。</p><h2 id="软件维护-⭐" tabindex="-1">软件维护 ⭐ <a class="header-anchor" href="#软件维护-⭐" aria-label="Permalink to &quot;软件维护 ⭐&quot;">​</a></h2><blockquote><p>记忆点</p></blockquote><ul><li>更正性维护 ：修复已发生的错误</li><li>预防性维护 ：预防潜在错误</li><li>适应性维护 ：适应变化进行的维护行为。</li><li>完善性维护 ：扩充功能、改善性能（考频更大）</li></ul><h2 id="软件风险管理" tabindex="-1">软件风险管理 <a class="header-anchor" href="#软件风险管理" aria-label="Permalink to &quot;软件风险管理&quot;">​</a></h2><p>风险的特性：具有不确定性，可能会造成损失。</p><p>风险的类别：</p><ul><li>项目风险涉及到各种形式的预算、进度、人员、资源以及客户相关的问题，并且可能导致项目损失。</li><li>技术风险涉及到技术相关的可能会导致项目损失的问题。</li><li>商业风险与市场因素相关。</li><li>社会风险涉及到政策、法规等因素。</li></ul><p>风险曝光度的公式 = 错误出现率(风险出现率) X 错误造成损失(风险损失)。</p><h2 id="软件质量" tabindex="-1">软件质量 <a class="header-anchor" href="#软件质量" aria-label="Permalink to &quot;软件质量&quot;">​</a></h2><h3 id="iso-iec9126-软件质量模型-⭐️" tabindex="-1">ISO/IEC9126 软件质量模型 ⭐️ <a class="header-anchor" href="#iso-iec9126-软件质量模型-⭐️" aria-label="Permalink to &quot;ISO/IEC9126 软件质量模型 ⭐️&quot;">​</a></h3><p>在 ISO/IEC9126软件质量模型 中，软件质量模型由三个层次组成，第一层为质量特性，第二层为质量子特性，第三层为度量指标。</p><p>如图所示 <img src="'+c+'" alt="ruankao_20250402172124.png" loading="lazy"></p><p>ISO/IEC 9126模型中，基本特性为6个：功能性、可靠性、易使用性、效率、可维护性和可移植性。</p><blockquote><p>常考记忆点 ⭐️⭐️⭐️</p></blockquote><table tabindex="0"><thead><tr><th>质量特性</th><th>对应的子特性</th></tr></thead><tbody><tr><td>功能性（功能准不准确）</td><td>准确性、安全性</td></tr><tr><td>可靠性（系统稳不稳）</td><td>成熟性、容错性、易恢复性</td></tr><tr><td>易使用性（用户是否能方便地使用系统）</td><td>易理解性、易学性、易操作性</td></tr><tr><td>效率（系统快不快）</td><td>时间特性、资源利用性</td></tr><tr><td>维护性（系统是否能方便地维护）</td><td>易分析性、易改变性、易测试性</td></tr><tr><td>可移植性（系统是否能在不同的环境中运行）</td><td>适应性、易安装性、一致性、易替换性</td></tr></tbody></table><blockquote><p>常考知识点 ⭐️⭐️⭐️</p></blockquote><ul><li>软件维护的工作量比开发阶段的工作量大</li><li>软件可维护性是一个系统在特定的时间间隔内可以正常进行维护活动的概率。用MTTF和MTTR分别表示平均无故障时间和平均故障修复时间，则软件可维护性计算公式为（ 1/(1+MTTR) ）</li><li>系统的可维护性指标：可理解性、可测试性和可修改性。</li></ul><h3 id="mccabe环路复杂度-⭐" tabindex="-1">McCabe环路复杂度 ⭐ <a class="header-anchor" href="#mccabe环路复杂度-⭐" aria-label="Permalink to &quot;McCabe环路复杂度 ⭐&quot;">​</a></h3><p>McCabe环路复杂度。有两种方式求出。</p><ul><li>公式法：先将程序的流程图转换为有向图。然后使用公式 V(G) = E - N + 2 。其中 E 是程序图中边的数量，N 是节点数量。</li><li>区域法：先数出图中封闭环的个数。环形复杂度等于封闭环个数+1。</li></ul><p><span style="color:red;">注意：封闭环个数不计算重叠的。</span></p><blockquote><p>真题案例</p></blockquote><p>若采用McCabe度量法计算环路复杂性，则对于下图所示的程序图，其环路复杂度为（ ）。</p><p><img src="'+x+'" alt="ruankao_20250514111327.png" loading="lazy"></p><p>考点：McCabe 度量法计算环路复杂度。</p><p>解法1 公式法</p><p>解题思路：McCabe 度量法计算环路复杂度公式为V(G) = E - N + 2，其中 E 是程序图中边的数量，N 是节点数量 。</p><p>由于图为有向图，因此从图中数出节点数 9 ，边数11 ，代入公式可得 V(G)=11 - 9 + 2 = 4。</p><p>解法2 区域法</p><p>程序图的环路数等于由程序图中封闭的区域数量加上 1。</p><p><span style="color:red;">注意：封闭环个数不计算重叠的。</span></p><p>如图图中封闭的区域数量为3。因此 环路复杂度 = 3 + 1 = 4</p><blockquote><p>真题案例</p></blockquote><p>对下图所示的程序流程图采用McCabe度量法计算其环路复杂度为（ ）。</p><p><img src="'+y+'" alt="ruankao_20250514113816.png" loading="lazy"></p><p>解法1 公式法</p><p>先将程序流程图转换为有向图。然后根据公式V(G) = E - N + 2 。其中 E 是程序图中边的数量，N 是节点数量。</p><p>如图  V(G)= 15 - 12 + 2 = 5</p><p>解法2 区域法</p><p><span style="color:red;">注意：封闭环个数不计算重叠的。</span></p><p>如图程序流程图的封闭环路数量为 6.因此该图的环路复杂度为6+1=7</p><blockquote><p>真题案例</p></blockquote><p>采用McCabe度量法计算下列程序图的环路复杂性为（）。</p><p><img src="'+M+'" alt="ruankao_20250514152906.png" loading="lazy"></p><p>环形度量采用封闭环个数+1的方式进行计算最简单也是最保险的方式。上图可以直接看出存在3个封闭环回路，整个环形复杂度就是3+1 = 4</p><p><span style="color:red;">注意：封闭环个数不计算重叠的。</span></p><blockquote><p>真题</p></blockquote><p><img src="'+I+'" alt="ruankao_20251107204141.png" loading="lazy"></p><p>试题分析:</p><p>环形复杂性计算公式为V(G) = E - N + 2，其中 E是流图中边(Edge)的条数，N是节点(Node)的个数。所以，V(G)=E-N+2=11-10+2=3。</p><p>答案: C</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><ul><li><p>以下软件产品中，属于图像编辑处理工具的软件是（ Photoshop ）。</p></li><li><p>某个项目在开发时采用了不成熟的前沿技术，由此而带来的风险属于（ 技术 ）风险。</p></li><li><p>软件开发过程中，需求分析阶段的输出不包括（ 软件体系结构图 ）。</p></li><li><p>软件详细设计阶段的主要任务不包括（ 模块之间的接口设计 ）。</p></li><li><p>信息系统的文档是开发人员与用户交流的工具。在系统规划和系统分析阶段,用户与系统分析人员交流所使用的文档不包括（ 用户使用手册 ）。</p></li><li><p>正式技术评审的目标是（ 发现软件中的错误 ）。</p></li><li><p>以下关于各类文档撰写阶段的叙述中，不正确的是（ 测试计划必须在测试阶段撰写 ）。</p></li><li><p>下列活动，（ 针对系统特点，考虑并确定系统开发平台与程序设计语言 ）不属于需求开发活动的范畴。</p></li><li><p>若用户需求不清晰且经常发生变化，但系统规模不太大且不太复杂，则最适宜采用（ 原型化 ）开发方法，对于数据处理领域的问题，若系统规模不太大且不太复杂，需求变化也不大，则最适宜采用（ 结构化 ）开发方法。</p></li><li><p>统一过程模型是一种“用例和风险驱动，以架构为中心，迭代并且增量”的开 发过程，定义了不同阶段及其制品，其中精化阶段关注（需求分析和架构演进）。</p></li><li><p>关于螺旋模型，下列陈述中不正确的是（ 可以快速的提供一个初始版本让用户测试 ）。</p></li><li><p>（ 瀑布 ）开发过程模型最不适用于开发初期对软件需求缺乏准确全面认识的情况。</p></li><li><p>喷泉模型是一种适合于面向（ 对象 ）开发方法的软件过程模型。该过程模型的特点不包括（ 开发活动之间存在明显的界限 ）。</p></li><li><p>某企业拟开发一个企业信息管理系统，系统功能与多个部门的业务相关。现希望该系统能够尽快投入使用，系统功能可以在使用过程中不断改善。则最适宜采用的软件过程模型为（ 演化（迭代）模型 ）。</p></li><li><p>以下关于快速原型模型优点的叙述中，不正确是（ 适用于大型软件系统的开发 ）。</p></li><li><p>（ 很容易将客户需求划分为多个增量 ）不是增量式开发的优势。</p></li><li><p>螺旋模型综合了__瀑布模型和演化模型___的优点，并增加了这两种模型忽略的风险分析。</p></li><li><p>确定软件的模块划分及模块之间的调用关系是（ 概要设计 ）阶段的任务。</p></li><li><p>敏捷开发方法Scrum的步骤不包括（ Refactoring ）。</p></li><li><p>以下关于极限编程(XP) 中结对编程的叙述中，不正确的是（ 编码速度更快 ）。</p></li><li><p>以下关于极限编程（XP）的最佳实践的叙述中，不正确的是（ 编写完程序之后编写测试代码 ）。</p></li><li><p>优化模块结构时，（ 使模块功能完整， 消除重复功能，改善软件结构，避免或减少模块之间的病态连接）是适当的处理方法。</p></li><li><p>在软件开发过程中，系统测试阶段的测试目标来自于（ 需求分析 ）阶段。</p></li><li><p>白盒测试技术的各种覆盖方法中，（ 语句覆盖 ）具有最弱的错误发现能力。</p></li><li><p>在设计测试用例时，应遵循（ 不仅要设计有效合理输入，也要包含不合理、失效的输入 ）原则。</p></li><li><p>在软件系统交付给用户使用后，为了使用户界面更友好，对系统的图形输出进行改进，该行为属于（ 改善性 ）维护。</p></li><li><p>以下关于软件测试的叙述中，正确的是（ 一个成功的测试能发现至今未发现的错误 ）。</p></li><li><p>以下关于进度管理工具Gantt图的叙述中，不正确的是 （ 能清晰地确定影响进度的关键任务 ） 。</p></li><li><p>针对“关键职员在项目未完成时就跳槽”的风险，最不合适的风险管理策略是（ 临时招聘具有相关能力的新职员 ）。</p></li><li><p>工作量估算模型COCOMO II的层次结构中,估算选择不包括（ 用例数 ）。</p></li></ul><blockquote><p>软件质量</p></blockquote><ul><li>按照 ISO/IEC 9126 软件质量度量模型定义，一个软件的可靠性的子特性包括（ 容错性和易恢复性 ）。</li><li>软件可维护性是一个系统在特定的时间间隔内可以正常进行维护活动的概率。用MTTF和MTTR分别表示平均无故障时间和平均故障修复时间，则软件可维护性计算公式为（ 1/(1+MTTR) ）。</li><li>在ISO/IEC软件质量模型中，可移植性是指与软件可从某环境行移到另一环境的能力有关的一组属性，其子特性不包括（ 测试性 ）。</li><li>在对程序质量进行评审时，模块结构是一个重要的评审项，评审内容中不包括（ 数据结构 ）。</li><li>在ISO/IEC9126软件质量模型中，软件质量特性（ 功能性 ）包含质量子特性安全性。</li><li>在IS0/IEC软件质量模型中，易使用性是指与使用所需的努力和由一组规定或隐含的用户对这样使用所作的个别评价有关的一组属性，其子特性不包括（ 易分析性 ）。</li><li>在ISO/IEC 9126软件质量模型中，可靠性质量特性是指在规定的一段时间内和规定的条件下，软件维持在其性能水平有关的能力，其质量子特性不包括（ 安全性 ，可移植性 ）。</li><li>（ 易理解性 ）不属于软件质量特性中的可移植性。</li><li>（ 功能与模块之间的对应关系 ）不属于软件设计质量评审。</li><li>在设计中实现可移植性设计的规则不包括（ 可使用特定环境的专用功能 ）</li><li>软件质量属性中，（ 吞吐量 ）是指软件每分钟可以处理多少个请求。</li><li>系统可维护性的评价指标不包括（ 可移植性 ）。</li><li>系统可维护性是指维护人员理解、改正、改动和改进软件系统的难易程度，其评价指标不包括（ 一致性 ）。</li><li>将每个用户的数据和其他用户的数据隔离开，是考虑了软件的（ 功能性 ）质量特件。</li></ul>',231)])])}const A=h(E,[["render",T]]);export{V as __pageData,A as default};
